async fn every_pooled_connection_has_recursive_triggers() {
    let (_dir, pool) = pool(3).await;
    let mut conns = Vec::new();
    for _ in 0..3 {
        conns.push(pool.acquire().await.expect("acquire"));
    }
    for conn in &mut conns {
        let on: i64 = sqlx::query_scalar("PRAGMA recursive_triggers")
            .fetch_one(&mut **conn)
            .await
            .expect("pragma");
        assert_eq!(on, 1);
    }
}

#[tokio::test(flavor = "multi_thread")]

async fn engine_collations_are_registered() {
    let (_dir, pool) = pool(3).await;
    sqlx::query(
        "CREATE TABLE t (v TEXT COLLATE ontoforge_decimal, ts TEXT COLLATE ontoforge_timestamp)",
    )
    .execute(&pool)
    .await
    .expect("create");
    sqlx::query("INSERT INTO t (v, ts) VALUES ('1.50', '2026-01-01 00:00:00.000')")
        .execute(&pool)
        .await
        .expect("insert");
    let decimal: i64 = sqlx::query_scalar("SELECT count(*) FROM t WHERE v = '1.5'")
        .fetch_one(&pool)
        .await
        .expect("decimal");
    assert_eq!(decimal, 1);
    let timestamp: i64 =
        sqlx::query_scalar("SELECT count(*) FROM t WHERE ts = '2026-01-01 00:00:00'")
            .fetch_one(&pool)
            .await
            .expect("timestamp");
    assert_eq!(timestamp, 1);
}

#[tokio::test(flavor = "multi_thread")]

fn hs256_round_trip_does_not_panic() {
    let secret = [7_u8; 32];
    let claims = Claims {
        sub: "user-1".to_owned(),
        exp: 4_102_444_800, // 2100-01-01
    };
    let token = encode(
        &Header::new(Algorithm::HS256),
        &claims,
        &EncodingKey::from_secret(&secret),
    )
    .expect("encode");
    let decoded = decode::<Claims>(
        &token,
        &DecodingKey::from_secret(&secret),
        &Validation::new(Algorithm::HS256),
    )
    .expect("decode");
    assert_eq!(decoded.claims.sub, "user-1");
}

async fn removing_indexed_keeps_index() {
    let t = sqlite_store().await;
    let first = aviation();
    reload(&t.store, &first, &ReloadOptions::default())
        .await
        .expect("first");
    let relaxed = with_indexed(&first, "Flight", "status", false);
    let out = reload(&t.store, &relaxed, &ReloadOptions::default())
        .await
        .expect("second");
    assert!(out.changed);
    assert!(out.ddl.is_empty(), "{:#?}", out.ddl);
    let flight = index_list(&t, "of_obj_flight").await;
    assert!(
        flight
            .iter()
            .any(|(name, _)| name == "of_ix_of_obj_flight_status"),
        "{flight:?}"
    );
    let again = reload(&t.store, &relaxed, &ReloadOptions::default())
        .await
        .expect("third");
    assert!(
        !again.changed,
        "the kept index must not make every reload a change"
    );
}

