fn principal_attrs_types() {
    let a = auth(
        "[auth.principal_attrs.tenantId]
claim = "tenant"
type = "string"
[auth.principal_attrs.level]
claim = "lvl"
type = "integer"
[auth.principal_attrs.admin]
claim = "adm"
type = "boolean"
[auth.principal_attrs.regions]
