async fn first_reload_on_pg_puts_edit_tables_in_edit_schema() {
    let t = pg_store().await;
    let out = reload(&t.store, &base(), &ReloadOptions::default())
        .await
        .expect("reload");
    assert!(out.changed);
    assert_eq!(out.def_version, Some(1));
    assert!(out.ddl.iter().all(|sql| sql.contains(&t.schema_edit)));

    let edit = t.tables(&t.schema_edit).await;
    assert_eq!(
        names(&edit),
        BTreeSet::from(["of_obj_gate", "of_obj_stand", "of_lnk_gate_stands"]),
        "edit tables only"
    );
    let sys = t.tables(&t.schema_sys).await;
    assert_eq!(
        names(&sys),
        BTreeSet::from([
            "_sqlx_migrations",
            "of_action_command",
            "of_def_state",
            "of_def_version",
            "of_admin_audit",
            "of_edit_history",
            "of_edit_log",
            "of_edit_log_entry",
            "of_role",
            "of_role_binding",
            "of_user",
            "of_read_audit",
            "of_webhook_outbox"
        ]),
        "system tables only"
    );
    assert_eq!(t.active_version().await, 1);
    assert_eq!(t.version_rows().await, 1);

    // ADR-0024 point 7: column types and collation.
    let gate = "of_obj_gate";
    assert_eq!(t.data_type(&t.schema_edit, gate, "code").await, "text");
    assert_eq!(
        t.collation(&t.schema_edit, gate, "code").await.as_deref(),
        Some("C")
    );
    assert_eq!(t.data_type(&t.schema_edit, gate, "cost").await, "numeric");
    assert_eq!(
        t.data_type(&t.schema_edit, gate, "opened_at").await,
        "timestamp with time zone"
    );
    assert_eq!(t.data_type(&t.schema_edit, gate, "tags").await, "ARRAY");
    assert_eq!(t.data_type(&t.schema_edit, gate, "location").await, "jsonb");
    assert_eq!(
        t.data_type(&t.schema_edit, gate, "name__set").await,
        "boolean"
    );
    assert_eq!(
        t.data_type(&t.schema_edit, gate, "of_version").await,
        "bigint"
    );
}

#[tokio::test(flavor = "multi_thread")]
#[ignore = "needs ONTOFORGE_PG_URL or --features embedded-pg"]

fn sql_text_only_from_sql_exit() {
    let rules = Rules::new();

    // The scanner must be able to see what it is looking for.
    let sample = "let a = \"SELECT 1\";\nlet b = AssertSqlSafe(x);\nlet c = \"selected\";\n\
                  let d = \"INSERT OR REPLACE INTO t\";\n// \"DROP\" AssertSqlSafe\n\
                  let e = \"REPLACE INTO t\";\n";
    assert_eq!(hits("sample.rs", sample, &rules.sql_literal).len(), 3);
    assert_eq!(hits("sample.rs", sample, &rules.assert_safe).len(), 1);
    assert_eq!(hits("sample.rs", sample, &rules.replacing).len(), 2);

    let src = Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
    let exit = src.join("sql_exit.rs");
    let mut found = Vec::new();
    let mut scanned = 0;
    let mut saw_exit = false;
    for entry in WalkDir::new(&src).into_iter().filter_map(Result::ok) {
        let path = entry.path();
        if path.extension().is_none_or(|e| e != "rs") {
            continue;
        }
        scanned += 1;
        let text = std::fs::read_to_string(path).unwrap();
        let rel = path.strip_prefix(&src).unwrap().display().to_string();
        found.extend(hits(&rel, &text, &rules.replacing));
        if path == exit {
            saw_exit = true;
            continue;
        }
        found.extend(hits(&rel, &text, &rules.sql_literal));
        found.extend(hits(&rel, &text, &rules.assert_safe));
    }
    assert!(
        scanned > 0,
        "no source files scanned under {}",
        src.display()
    );
    assert!(
        saw_exit,
        "src/sql_exit.rs was not found: the guard is stale"
    );
    assert!(
        found.is_empty(),
        "SQL text outside src/sql_exit.rs, or a replacing conflict clause:\n{}",
        found.join("\n")
    );
}

