fn migrate_plan_then_apply() {
    let ws = Workspace::new(GATE_WITH_CAPACITY);
    let first = ws.run("reload", &[]);
    assert_eq!(first.status.code(), Some(0), "stderr: {}", stderr(&first));

    ws.set_gate(GATE_WITHOUT_CAPACITY);
