fn drop_archived_plan_and_apply() {
    let ws = Workspace::new(GATE_WITH_CAPACITY);
    assert_eq!(ws.run("reload", &[]).status.code(), Some(0));
    ws.set_gate(GATE_WITHOUT_CAPACITY);
    let plan = ws.run("migrate", &["--plan"]);
    let hash = plan_hash(&plan);
    let applied = ws.run("migrate", &["--apply", "--plan-hash", &hash]);
    assert_eq!(
        applied.status.code(),
        Some(0),
        "stderr: {}",
        stderr(&applied)
    );

    let drop_plan = ws.run("migrate", &["--drop-archived", "--plan"]);
    assert_eq!(
        drop_plan.status.code(),
        Some(0),
        "stderr: {}",
        stderr(&drop_plan)
    );
    assert!(
        stdout(&drop_plan).contains("drop archived column of_obj_gate.capacity__arch_v2"),
        "{}",
        stdout(&drop_plan)
    );
    let drop_hash = plan_hash(&drop_plan);

    let dropped = ws.run(
        "migrate",
        &["--drop-archived", "--apply", "--plan-hash", &drop_hash],
    );
    assert_eq!(
        dropped.status.code(),
        Some(0),
        "stderr: {}",
        stderr(&dropped)
    );
    assert!(
        stderr(&dropped).contains("def_version 3"),
        "{}",
        stderr(&dropped)
    );

    let nothing = ws.run("migrate", &["--drop-archived", "--plan"]);
    assert!(
        stdout(&nothing).contains("no migration steps needed"),
        "{}",
        stdout(&nothing)
    );
}

#[test]

async fn migrate_waits_for_trino_after_the_switch() {
    // `capacity` goes away: migrate archives the column, which cannot be undone by a retry, so
    // the definition switches in one transaction and Trino is awaited afterwards.
    let removed = definition(
        "code",
        "  code: { type: string, required: true }\n  name: { type: string }\n",
        true,
    );
    let t = sqlite_store().await;
    reload(&t.store, &base(), &ReloadOptions::default())
        .await
        .expect("v1");
    let active = t.store.active_definition().await.expect("active");
    let plan = plan_migration(&active, &removed, &[]).expect("plan");

    let blind = ScriptedTrino::gate(usize::MAX, &["capacity__arch_v2"]);
    let probe = ProbeContext {
        target: &blind,
        catalog: "editstore".to_owned(),
        timeout: std::time::Duration::from_millis(300),
    };
    let result =
        apply_migration_probed(&t.store, &removed, &[], &plan.hash, Some(&probe), None).await;
    let Err(MigrateError::NotVisible { missing }) = result else {
        panic!("expected NotVisible, got {result:?}");
    };
    assert_eq!(missing, ["of_obj_gate.capacity__arch_v2"]);
    assert_eq!(
        t.active_version().await,
        2,
        "the migration itself is applied"
    );

    // With a Trino that shows the archived column the call returns the new version.
    let t = sqlite_store().await;
    reload(&t.store, &base(), &ReloadOptions::default())
        .await
        .expect("v1");
    let seeing = ScriptedTrino::gate(2, &["capacity__arch_v2"]);
    let probe = ProbeContext {
        target: &seeing,
        catalog: "editstore".to_owned(),
        timeout: std::time::Duration::from_secs(5),
    };
    let version = apply_migration_probed(&t.store, &removed, &[], &plan.hash, Some(&probe), None)
        .await
        .expect("migrate");
    assert_eq!(version, 2);
    assert_eq!(seeing.describes(), 2);
    assert_eq!(seeing.flushes(), ["editstore"]);
}

