/// The three ways to be unable to see `F1`, as the errors of one store.

async fn stale_writer_rejected_after_switch() {
    let t = sqlite_store().await;
    reload(&t.store, &base(), &ReloadOptions::default())
        .await
        .expect("v1");
    // A second process: it opened the store while definition 1 was active.
    let writer = t.reopen().await;
    writer
        .commit(gate_commit(1, "A1", &[("name", "North")]))
        .await
        .expect("a commit for the active definition");

    let out = reload(&t.store, &with_zone(), &ReloadOptions::default())
        .await
        .expect("v2");
    assert_eq!(out.def_version, Some(2));

    // The writer still holds definition 1 in memory; the database says 2.
    let err = writer
        .commit(gate_commit(1, "A2", &[("name", "South")]))
        .await
        .expect_err("a commit for a definition that is no longer active");
    assert!(
        matches!(
            err,
            EditError::DefinitionStale {
                expected: 1,
                active: 2
            }
        ),
        "{err:?}"
    );
    assert_eq!(count(&t, "of_obj_gate").await, 1, "no gate row was written");
    assert_eq!(
        count(&t, "of_edit_log").await,
        1,
        "no log record was written"
    );

    // The refusal refreshed the writer's definition from the database.
    assert_eq!(
        writer.active_definition().await.map(|a| a.def_version),
        Some(2)
    );
    writer
        .commit(gate_commit(2, "A2", &[("zone", "Z1")]))
        .await
        .expect("a commit for definition 2 may use the property it added");
    assert_eq!(count(&t, "of_obj_gate").await, 2);
}

#[tokio::test(flavor = "multi_thread")]

async fn in_flight_commit_blocks_switch_on_pg() {
    let t = pg_store().await;
    reload(&t.store, &base(), &ReloadOptions::default())
        .await
        .expect("v1");
    // Another process that opened the store while definition 1 was active.
    let writer = t.open_another(Duration::from_secs(5)).await;

    // What a commit holds between its fence read and its commit: a share lock on the state row.
    let mut in_flight = t.side().begin().await.expect("begin");
    let lock = format!(
        "SELECT active_def_version FROM \"{}\".of_def_state FOR SHARE",
        t.schema_sys
    );
    let held: i64 = sqlx::query_scalar(sqlx::AssertSqlSafe(lock))
        .fetch_one(&mut *in_flight)
        .await
        .expect("share lock");
    assert_eq!(held, 1);

    let store = std::sync::Arc::clone(&t.store);
    let switching =
        tokio::spawn(async move { reload(&store, &with_zone(), &ReloadOptions::default()).await });
    tokio::time::sleep(Duration::from_millis(700)).await;
    assert!(
        !switching.is_finished(),
        "the switch must wait for the commit in flight"
    );
    assert_eq!(t.active_version().await, 1);

    in_flight.commit().await.expect("the commit in flight ends");
    let out = switching
        .await
        .expect("join")
        .expect("the switch goes through once the commit ended");
    assert_eq!(out.def_version, Some(2));

    let err = writer
        .commit(gate_commit(1, "A1", "North"))
        .await
        .expect_err("a write for the old definition is refused after the switch");
    assert!(
        matches!(
            err,
            EditError::DefinitionStale {
                expected: 1,
                active: 2
            }
        ),
        "{err:?}"
    );
    writer
        .commit(gate_commit(2, "A1", "North"))
        .await
        .expect("a write for the new definition goes through");
}

