async fn pg_migrate_rechecks_applied_roles() {
    let t = pg_store().await;
    let aviation = load_aviation(camino::Utf8Path::new(AVIATION_DIR));
    reload(
        &t.store,
        &aviation,
        &ReloadOptions {
            roles: Some(roles_check()),
            ..ReloadOptions::default()
        },
    )
    .await
    .expect("v1");
    let out = ontoforge_schema::load_scope_dir(camino::Utf8Path::new(AVIATION_SCOPE));
    assert!(out.diagnostics.is_empty(), "{:#?}", out.diagnostics);
    let scope = out.scope.expect("aviation scope");
    let check = roles_check();
    let compiled = ontoforge_auth::scope::compile_scope(&ontoforge_auth::scope::ScopeInputs {
        ontology: &aviation,
        profile: None,
        attrs: &check.attrs,
        scope: &scope,
        sources: None,
    })
    .unwrap_or_else(|d| panic!("{d:#?}"));
    let props = compiled.row_filter_properties();
    let scope_plan = t
        .store
        .scope_plan(&scope, &props)
        .await
        .expect("scope plan");
    t.store
        .scope_apply(&scope, &props, &scope_plan.hash, "tester@testhost")
        .await
        .expect("scope apply");

    let new = aviation_without_city();
    let active = t.store.active_definition().await.expect("active");
    let hash = plan_migration(&active, &new, &[]).expect("plan").hash;
    let airport_before = t.columns(&t.schema_edit, "of_obj_airport").await;
    assert!(
        airport_before.contains(&"city".to_owned()),
        "{airport_before:?}"
    );

    let result =
        apply_migration_probed(&t.store, &new, &[], &hash, None, Some(&roles_check())).await;
    let Err(MigrateError::Definition(diagnostics)) = result else {
        panic!("expected a definition error, got {result:?}");
    };
    assert!(!diagnostics.is_empty());
    assert!(
        diagnostics.iter().all(|d| d.code == "ONT-V21"),
        "{diagnostics:#?}"
    );
    assert!(
        diagnostics
            .iter()
            .any(|d| d.message.contains("dispatcher") && d.message.contains("city")),
        "the diagnostic names the role and the property: {diagnostics:#?}"
    );
    let airport_after = t.columns(&t.schema_edit, "of_obj_airport").await;
    assert_eq!(airport_after, airport_before, "no step ran");
    assert!(
        !airport_after.iter().any(|c| c == "city__arch_v2"),
        "{airport_after:?}"
    );
    assert_eq!(t.active_version().await, 1);
    assert_eq!(t.version_rows().await, 1);

    // Without the role check the very same migration goes through: the roles stopped it.
    let version = apply_migration(&t.store, &new, &[], &hash)
        .await
        .expect("without the role check");
    assert_eq!(version, 2);
}

fn migrate_refuses_a_change_that_breaks_an_applied_role() {
    // The example server configuration declares `homeAirports`, which crewScheduler reads.
    let dir = tempfile::tempdir().expect("tempdir");
    let text = std::fs::read_to_string(DEV_CONFIG).expect("example server config");
    assert!(
        text.contains(DEV_STORE_PATH),
        "the example store path moved"
    );
    let config_path = dir.path().join("ontoforge-server.toml");
    std::fs::write(&config_path, text.replace(DEV_STORE_PATH, "edit.db")).expect("write config");
    let config = config_path.to_str().expect("utf-8 path");

    let first = ontoforge(&["reload", AVIATION, "--server-config", config]);
    assert_eq!(first.status.code(), Some(0), "stderr: {}", stderr(&first));
    let scope_plan = ontoforge(&[
        "scope",
        "plan",
        AVIATION_SCOPE,
        "--ontology",
        AVIATION,
        "--server-config",
        config,
    ]);
    assert_eq!(
        scope_plan.status.code(),
        Some(0),
        "stderr: {}",
        stderr(&scope_plan)
    );
    let scope_hash = plan_hash_line(&scope_plan);
    let apply = ontoforge(&[
        "scope",
        "apply",
        AVIATION_SCOPE,
        "--ontology",
        AVIATION,
        "--server-config",
        config,
        "--plan-hash",
        &scope_hash,
    ]);
    assert_eq!(apply.status.code(), Some(0), "stderr: {}", stderr(&apply));

    // A definition without `Airport.city`, a property the dispatcher role lists.
    let changed = tempfile::tempdir().expect("tempdir");
    copy_dir(Path::new(AVIATION), changed.path());
    let objects = changed.path().join("objects.yaml");
    let from = "  city: { type: string, displayName: City }\n";
    let objects_text = std::fs::read_to_string(&objects).expect("read");
    assert!(objects_text.contains(from), "objects.yaml lost `city`");
    std::fs::write(&objects, objects_text.replace(from, "")).expect("write");
    let changed_dir = changed.path().to_str().expect("utf-8 path");

    let plan = ontoforge(&["migrate", changed_dir, "--server-config", config, "--plan"]);
    assert_eq!(plan.status.code(), Some(0), "stderr: {}", stderr(&plan));
    let hash = plan_hash_line(&plan);

    let refused = ontoforge(&[
        "migrate",
        changed_dir,
        "--server-config",
        config,
        "--apply",
        "--plan-hash",
        &hash,
    ]);
    assert_eq!(
        refused.status.code(),
        Some(1),
        "stderr: {}",
        stderr(&refused)
    );
    let out = stdout(&refused);
    assert!(out.contains("ONT-V21"), "{out}");
    assert!(out.contains("dispatcher"), "the role is named: {out}");
    assert!(out.contains("city"), "the property is named: {out}");
    assert!(
        stderr(&refused).contains("migrate failed, the edit store was not changed"),
        "{}",
        stderr(&refused)
    );

    // The definition did not move: the same plan is still offered from def_version 1.
    let again = ontoforge(&["migrate", changed_dir, "--server-config", config, "--plan"]);
    assert_eq!(again.status.code(), Some(0), "stderr: {}", stderr(&again));
    assert!(
        stdout(&again).contains("from def_version 1"),
        "{}",
        stdout(&again)
    );
}

