        )
        .await
        .unwrap();
    assert_eq!(
        first.edits.iter().map(|e| &e.to).collect::<Vec<_>>(),
        vec![&PropertyValue::Int(1), &PropertyValue::Int(2)]
    );
    assert!(first.edits[0].row.deleted);
    assert_eq!(first.edits[0].row.version, 2);
    assert!(first.has_more);
    let second = fixture
        .store
        .read_link_edits(
            &active,
            &link("gateStands"),
            LinkEndpoint::From(s("A")),
