        second.edits.iter().map(|e| &e.to).collect::<Vec<_>>(),
        vec![&PropertyValue::Int(3)]
    );
    assert!(!second.has_more);
    let reverse = fixture
        .store
        .read_link_edits(
            &active,
            &link("gateStands"),
            LinkEndpoint::To(PropertyValue::Int(1)),
            None,
            2,
        )
        .await
        .unwrap();
    assert_eq!(
        reverse.edits.iter().map(|e| &e.from).collect::<Vec<_>>(),
        vec![&s("A"), &s("B")]
    );
    assert!(
        fixture
            .store
            .read_link_edits(
                &active,
                &link("gateStands"),
                LinkEndpoint::From(s("A")),
