        Err(ontoforge_query::QueryError::WorkBudgetExceeded)
    ));
}

fn valid_same_type_set_and_cross_type_rejection() {
    let ontology = load_dir(Utf8Path::new(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../examples/ontologies/aviation"
    )))
    .ontology
    .unwrap();
    let flight = ObjectTypeName::try_from("Flight".to_owned()).unwrap();
    let scope = TypeScope {
        row: Pred::Const(true),
        columns: ontology.object_types[&flight]
            .properties
            .keys()
            .cloned()
            .map(|name| (name, Pred::Const(true)))
            .collect(),
    };
    let wire = json!({
        "kind": "union", "object_type": "Flight", "sets": [
            {"kind": "type", "object_type": "Flight"},
            {"kind": "pk", "object_type": "Flight", "pk": "F-1001"}
        ]
    });
    let validate = |set| {
        ValidatedQuery::new(
            QueryRequest {
                set,
                select: vec![],
            },
            vec![],
            PageSpec {
                first: 10,
                after: None,
            },
            &ontology,
            &scope,
            CompileLimits::default(),
        )
    };
    assert!(validate(serde_json::from_value(wire.clone()).unwrap()).is_ok());
    let mut cross_type = wire;
    cross_type["sets"][1]["object_type"] = json!("Airport");
    assert!(matches!(
        validate(serde_json::from_value(cross_type).unwrap()),
        Err(QueryError::InvalidQuery)
    ));

    let empty: ObjectSet = serde_json::from_value(json!({
        "kind": "union", "object_type": "Flight", "sets": []
    }))
    .unwrap();
    assert!(matches!(validate(empty), Err(QueryError::InvalidQuery)));

    let nested: ObjectSet = serde_json::from_value(json!({
        "kind": "union", "object_type": "Flight", "sets": [
            {"kind": "intersect", "object_type": "Flight", "sets": [
                {"kind": "type", "object_type": "Flight"}
            ]}
        ]
    }))
    .unwrap();
    let tight = CompileLimits {
        max_depth: 2,
        ..CompileLimits::default()
    };
    assert!(matches!(
        ValidatedQuery::new(
            QueryRequest {
                set: nested,
                select: vec![]
            },
            vec![],
            PageSpec {
                first: 10,
                after: None
            },
            &ontology,
            &scope,
            tight,
        ),
        Err(QueryError::QueryTooComplex)
    ));

    let nested_operands: ObjectSet = serde_json::from_value(json!({
        "kind": "union", "object_type": "Flight", "sets": [
            {"kind": "union", "object_type": "Flight", "sets": [
                {"kind": "type", "object_type": "Flight"},
                {"kind": "type", "object_type": "Flight"}
            ]},
            {"kind": "type", "object_type": "Flight"}
        ]
    }))
    .unwrap();
    let tight_operands = CompileLimits {
        max_in_values: 2,
        ..CompileLimits::default()
    };
    assert!(matches!(
        ValidatedQuery::new(
            QueryRequest {
                set: nested_operands,
                select: vec![]
            },
            vec![],
            PageSpec {
                first: 10,
                after: None
            },
            &ontology,
            &scope,
            tight_operands,
        ),
        Err(QueryError::QueryTooComplex)
    ));

    let predicates: ObjectSet = serde_json::from_value(json!({
        "kind": "union", "object_type": "Flight", "sets": [
            {"kind": "where", "object_type": "Flight", "predicate": {"op": "isNull", "property": "status"}},
            {"kind": "where", "object_type": "Flight", "predicate": {"op": "isNull", "property": "status"}},
            {"kind": "where", "object_type": "Flight", "predicate": {"op": "isNull", "property": "status"}}
        ]
    })).unwrap();
    let node_limit = CompileLimits {
        max_nodes: 6,
        ..CompileLimits::default()
    };
    assert!(matches!(
        ValidatedQuery::new(
            QueryRequest {
                set: predicates,
                select: vec![]
            },
            vec![],
            PageSpec {
                first: 10,
                after: None
            },
            &ontology,
            &scope,
            node_limit,
        ),
        Err(QueryError::QueryTooComplex)
    ));
}

