    assert_eq!(first.rows.len(), 1);
    assert_eq!(first.rows[0].pk, json!("F-1001"));
    assert!(first.has_more);
    let second = service.execute_list(&query(first.cursor)).await.unwrap();
    assert_eq!(second.rows.len(), 1);
    assert_eq!(second.rows[0].pk, json!("F-1002"));
    assert!(!second.has_more);

    let targeted = QueryService {
        principal: &principal,
        scope: &scope,
        active: Arc::clone(&active),
        engine: &engine,
        store: &store,
        limits: ExecutionLimits::try_new(6, 4, 2, 64 * 1024 * 1024).unwrap(),
        tokens: &tokens,
    };
    assert_eq!(
        targeted.execute_list(&query(None)).await.unwrap().rows[0].pk,
